output application/json

// Accedemos a los datos desde la variable RequestOrder
var inputData = vars.RequestOrder default {}

var orderNum = vars.resultadoConsecutivo.result.value.Prefijo default "" ++ (vars.resultadoConsecutivo.result.value.Secuencia as String)

// Función para formatear fechas al estilo MongoDB
fun toDate(d) = if (isEmpty(d)) null else { "\$date": d }

---
{ 
	"query" : {
 "insert": "MDM_CD_ORDEN",
  "documents": [
    {
  "Fecha_Creacion": toDate(inputData.createdAt),
  "Fecha_Modificacion": toDate(inputData.updatedAt),
  "Usuario_Modificacion": inputData.updatedBy,
  "Usuario_Creacion": inputData.createdBy,
  "Actualizacion_Extractor": inputData.extractorUpdate,
  "Numero_Orden": orderNum as String,
  "Canal": inputData.channel,
  "Fase": inputData.phase,

  "Estado_Orden_Comercial": {
    "Codigo": inputData.commercialOrderStatus.code,
    "Descripcion": inputData.commercialOrderStatus.description,
    "Fecha": toDate(inputData.commercialOrderStatus.date),
    "Reintentos": inputData.commercialOrderStatus.retries,
    "CodigoExcepcion": inputData.commercialOrderStatus.exceptionCode,
    "Excepcion": inputData.commercialOrderStatus.exception
  },

  "Tramite": {
    "Tipo_Tramite": inputData.through.throughType,
    "Subtipo_Tramite": if (isEmpty(inputData.through.throughSubtype)) null else inputData.through.throughSubtype,
    "Fecha_Tramite": toDate(inputData.through.throughDate),
    "Fecha_Reconexion": toDate(inputData.through.reconnectionDate),
    "Fecha_Suspension": toDate(inputData.through.suspensionDate),
    "Fecha_Ejecucion": toDate(inputData.through.executionDate),
    "Conservar_Numero_Conexion": inputData.through.keepConnectionNumber,
    "Clausula_Permanencia": inputData.through.permanenceClause,
    "Valor_Clausula_Permanencia": inputData.through.permanenceClauseValue,
    "Causal_Cancelacion": if (isEmpty(inputData.through.cancellationReason)) null else inputData.through.cancellationReason,
    "Subcausal_Cancelacion": if (isEmpty(inputData.through.cancellationSubreason)) null else inputData.through.cancellationSubreason,
    "Descripcion_Cancelacion": if (isEmpty(inputData.through.cancellationDescription)) null else inputData.through.cancellationDescription,
    "MotivosOrden": if (isEmpty(inputData.through.orderMotives)) null else inputData.through.orderMotives
  },

  "CUN": inputData.cun,

  "Cliente_Tramite": {
    "Tipo_Documento": inputData.requestCustomer.documentType,
    "Numero_Documento": inputData.requestCustomer.documentNumber,
    "Nombres": inputData.requestCustomer.firstName,
    "Primer_Apellido": inputData.requestCustomer.firstLastName,
    "Segundo_Apellido": inputData.requestCustomer.secondLastName,
    "Fecha_Expedicion": toDate(inputData.requestCustomer.expeditionDate),
    "UEN": inputData.requestCustomer.businessUnit,
    "Segmento": inputData.requestCustomer.segment,
    "Email": inputData.requestCustomer.email,
    "Telefono_Movil": inputData.requestCustomer.mobilePhone,

    "Contactos": inputData.requestCustomer.contacts map (contact, index) -> {
      "_id": { "\$oid": contact.id },
      "Tipo_Documento": contact.documentType,
      "Numero_Documento": contact.documentNumber,
      "Nombres": contact.firstName,
      "Primer_Apellido": contact.firstLastName,
      "Departamento": contact.state,
      "Ciudad": contact.city,
      "Direccion": contact.address,
      "Autorizado": contact.isAuthorized
    },

    "Direcciones": inputData.requestCustomer.addresses map (addr, index) -> {
      "Id_Direccion": addr.addressId,
      "Direccion_Normalizada": addr.normalizedAddress,
      "Tipo_Direccion": addr.addressType,
      "Departamento": addr.state,
      "Municipio": addr.municipality,
      "Estado": addr.status,
      "Seleccionada": addr.isSelected,
      "Cobertura": if (addr.coverage != null) {
        "Tipo_Cobertura": addr.coverage.coverageType,
        "Estrato": addr.coverage.stratum,
        "Tecnologia": addr.coverage.technology,
        "Viable": addr.coverage.isViable
      } else null
    }
  },

  "Servicio_Tramite": {
    "Id_Cuenta_Servicio": inputData.requestService.serviceAccountId,
    "Bundle": {
      "_id": { "\$oid": inputData.requestService.bundle.id },
      "Nombre": inputData.requestService.bundle.name,
      "Estado": inputData.requestService.bundle.status,
      "Precio_Oferta": inputData.requestService.bundle.offerPrice map (price) -> {
        "Precio_Sin_Iva": price.priceWithoutTax,
        "Precio_Con_Iva": price.priceWithTax,
        "Iva": price.tax
      },
      "Parametros_bundle": inputData.requestService.bundle.bundleParameters map (param) -> {
        "Parametro": param.parameter,
        "Valor": param.value
      }
    }
  }
}

]

}

}

